//! Shared `sq` (sequoia-sq) harness for the live cross-tool interop tests.
//!
//! Mirrors `common/gnupg.rs`: an isolated `sq --home` per test plus a
//! probe-or-skip gate. With `CYPHERAIR_REQUIRE_SQ=1`, a missing sq, or one
//! that cannot read the final RFC 9980 post-quantum encoding, fails instead of
//! skipping. Fixtures generated by `fixtures/generate_sq_fixtures.sh` keep the
//! committed side deterministic.

use std::path::PathBuf;
use std::process::Command;
use std::sync::OnceLock;

use cypher_engine::KeyShape;
use tempfile::TempDir;

use super::keys;

/// Resolve the `sq` binary, honoring the skip-forbidden gate.
pub fn require_sq_or_skip() -> Option<PathBuf> {
    match find_sq() {
        Some(path) => Some(path),
        None => {
            if sq_is_required() {
                panic!(
                    "CYPHERAIR_REQUIRE_SQ=1 but sq was not found on PATH or known locations; \
                     the mandatory sq interop lane must not skip"
                );
            }
            eprintln!(
                "sq not found on this system; skipping (set CYPHERAIR_REQUIRE_SQ=1 to forbid skips)"
            );
            None
        }
    }
}

fn sq_is_required() -> bool {
    std::env::var_os("CYPHERAIR_REQUIRE_SQ").is_some_and(|value| value == "1")
}

/// Resolve an `sq` that can also read final-RFC-9980 post-quantum artifacts.
///
/// An sq built on sequoia-openpgp before 2.4 rejects the engine's ML-DSA
/// certificates as malformed. The probe is functional: `sq key import` of an
/// engine post-quantum key, the same operation the live tests perform, must
/// succeed. ML-DSA-65 stands in for both post-quantum tiers.
pub fn require_pq_capable_sq_or_skip() -> Option<PathBuf> {
    static PQ_CAPABLE: OnceLock<bool> = OnceLock::new();

    let sq = require_sq_or_skip()?;
    if *PQ_CAPABLE.get_or_init(|| sq_imports_engine_pq_key(&sq)) {
        return Some(sq);
    }
    if sq_is_required() {
        panic!(
            "CYPHERAIR_REQUIRE_SQ=1 but sq at {} cannot read final RFC 9980 post-quantum \
             artifacts; install an sq built on sequoia-openpgp 2.4 or later",
            sq.display()
        );
    }
    eprintln!(
        "sq at {} cannot read final RFC 9980 post-quantum artifacts; skipping",
        sq.display()
    );
    None
}

/// Only an `sq key import` rejection counts as "not PQ-capable". A failure to
/// set the probe up says nothing about sq, so it panics.
fn sq_imports_engine_pq_key(sq_path: &PathBuf) -> bool {
    let key = keys::new_key(KeyShape::V6MlDsa65, "Probe");
    let home = setup_sq_home();
    let tsk_path = home.path().join("pq_probe_key.asc");
    std::fs::write(&tsk_path, keys::tsk(&key)).expect("write the probe key");

    let output = sq_cmd(sq_path, &home)
        .arg("key")
        .arg("import")
        .arg(&tsk_path)
        .output()
        .unwrap_or_else(|error| panic!("failed to run sq at {}: {error}", sq_path.display()));
    if output.status.success() {
        return true;
    }
    eprintln!(
        "post-quantum capability probe: `sq key import` rejected an engine ML-DSA-65 key:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
    false
}

/// Search for a working `sq` binary: PATH first, then common Homebrew/system
/// paths. A candidate counts only if `sq version` actually runs.
pub fn find_sq() -> Option<PathBuf> {
    let mut candidates = vec![PathBuf::from("sq")];
    candidates.extend(
        ["/opt/homebrew/bin/sq", "/usr/local/bin/sq", "/usr/bin/sq"]
            .iter()
            .map(PathBuf::from),
    );
    candidates.into_iter().find(|candidate| {
        Command::new(candidate)
            .arg("version")
            .output()
            .is_ok_and(|output| output.status.success())
    })
}

/// A temporary `sq --home`, so that tests never touch the user's stores.
pub fn setup_sq_home() -> TempDir {
    TempDir::new().expect("Failed to create temp sq home")
}

pub fn sq_cmd(sq_path: &PathBuf, home: &TempDir) -> Command {
    let mut cmd = Command::new(sq_path);
    cmd.arg("--home").arg(home.path());
    cmd
}

/// Run an sq command to completion, asserting success and returning stdout.
pub fn run_sq(mut cmd: Command, context: &str) -> Vec<u8> {
    let output = cmd
        .output()
        .unwrap_or_else(|e| panic!("Failed to run sq ({context}): {e}"));
    assert!(
        output.status.success(),
        "sq {context} failed:\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    );
    output.stdout
}
